/* Shared slide content — positioning and typography. Shell chrome lives in
   slidedeck (windowed HUD) or canvas-deck (full-bleed), not here. */
#xframe { overflow: visible; }
.segment { position: absolute; inset: 0; padding: {{slidePadY}} {{slidePadX}}; display: none; overflow: auto; }
.segment h1, .segment h2, .segment h3, .segment h4, .segment h5, .segment h6 { margin: 0; line-height: 1.2; color: var(--fg); }
.segment h1 { font-size: {{h1Size}}rem; line-height: {{h1LineHeight}}; }
.segment h2 { font-size: {{h2Size}}rem; line-height: {{h2LineHeight}}; }
.segment h3 { font-size: {{h3Size}}rem; line-height: {{h3LineHeight}}; }
.segment p, .segment li { margin: 0; font-size: {{bodySize}}rem; line-height: {{bodyLineHeight}}; }
.segment ul, .segment ol { margin: 0; padding-left: 1.4rem; }
.segment table { border-collapse: collapse; width: max-content; max-width: 100%; font-size: 1.1rem; }
.segment th, .segment td { border: 1px solid var(--border); padding: {{tableCell}} 0.75rem; text-align: left; }
.segment img { max-width: 100%; max-height: 60%; object-fit: contain; }
.segment figure.xframe-segment-snapshot { min-height: 0; max-height: 100%; margin: 0; gap: .35rem; }
.segment figure.xframe-segment-snapshot img,
.segment img[data-xframe-segment] { max-width: 100%; max-height: 100%; width: auto; height: auto; min-height: 0; object-fit: contain; }
.segment .xframe-html-host {
  position: relative;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  width: 100%;
  height: 100%;
  max-height: 100%;
  overflow: hidden;
}
.segment .xframe-html-host iframe.xframe-html {
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-height: 0;
  border: 0;
  background: transparent;
  overflow: hidden;
}
.segment pre { margin: 0; padding: .85rem 1rem; background: var(--code-bg); border: 1px solid var(--border); border-radius: 6px; overflow: auto; font-size: {{monoSize}}rem; }
[data-region="footer-right"] {
  text-align: right;
  color: var(--muted);
  font-size: 0.9em;
  font-variant-numeric: tabular-nums;
}

/* positioning:dynamic — flex layout solver */
#xframe[data-xframe-positioning="dynamic"] .layout-container.layout-stack { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; min-width: 0; }
#xframe[data-xframe-positioning="dynamic"] .layout-container[data-layout-direction="horizontal"] { flex-direction: row; }
#xframe[data-xframe-positioning="dynamic"] > .layout-container { height: 100%; }
#xframe[data-xframe-positioning="dynamic"] .layout-segments { position: relative; flex: 1 1 auto; min-height: 0; overflow: hidden; }
#xframe[data-xframe-positioning="dynamic"] .layout-container > :is(.region, .layout-container) {
  flex-grow: var(--layout-weight, 0);
  flex-shrink: var(--layout-shrink, 1);
  flex-basis: var(--layout-basis, 0%);
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
#xframe[data-xframe-positioning="dynamic"] .segment { flex-direction: column; justify-content: center; gap: {{gap}}; }
#xframe[data-xframe-positioning="dynamic"] .segment.active { display: flex; }
#xframe[data-xframe-positioning="dynamic"] .segment > .layout-container { display: flex; flex: 1 1 auto; flex-direction: column; min-height: 0; }
#xframe[data-xframe-positioning="dynamic"] .segment > .layout-container > .layout-default-region { display: flex; flex: 1 1 auto; flex-direction: column; min-height: 0; }
#xframe[data-xframe-positioning="dynamic"] .segment figure.xframe-segment-snapshot { flex: 1 1 auto; display: flex; flex-direction: column; align-items: center; }
#xframe[data-xframe-positioning="dynamic"] .segment figure.xframe-segment-snapshot img,
#xframe[data-xframe-positioning="dynamic"] .segment img[data-xframe-segment] { flex: 1 1 auto; }

/* positioning:static — compile-time solved boxes */
#xframe[data-xframe-positioning="static"] .layout-container,
#xframe[data-xframe-positioning="static"] .layout-segments,
#xframe[data-xframe-positioning="static"] .region { position: absolute; display: block; min-width: 0; min-height: 0; overflow: hidden; }
#xframe[data-xframe-positioning="static"] .segment.active { display: block; }
