```css
/* Windowed slidedeck chrome: letterboxed frame, HUD, fullscreen overlay. */

:root:fullscreen,
:root:fullscreen body { overflow: hidden; }
:root:fullscreen body {
  padding: 28px 20px 56px;
  box-sizing: border-box;
}
:root:fullscreen #xframe { border: 0; border-radius: 0; box-shadow: none; overflow: hidden; }
:root:fullscreen #xframe[data-xframe-canvas] { overflow: visible; }

html, body {
  height: 100%;
  overflow: hidden;
}

body {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 100%;
  box-sizing: border-box;
}

/* deck — outer shell; fullscreen target (experiment #deck) */
#xframe-deck {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 100%;
  max-height: 100%;
  overflow: hidden;
}

#xframe[data-xframe-canvas] {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: min(var(--canvas-w), calc(100vw - 2 * {{pagePadding}}));
  max-height: calc(100svh - 2 * {{pagePadding}});
  height: auto;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
  overflow: visible;
  transform: none !important;
  flex: 0 1 auto;
  min-height: 0;
  --xframe-frame-avail-h: calc(100svh - 2 * {{pagePadding}} - var(--xframe-chrome-h, 0px));

  & > .xframe-frame-host {
    flex: 0 0 auto;
    width: 100%;
  }

  &:has(.xframe-ai-index-control:not([hidden])) {
    margin-left: calc(var(--xframe-ai-index-rail) + var(--xframe-ai-index-gap));
    max-width: min(var(--canvas-w), calc(100vw - 2 * {{pagePadding}} - var(--xframe-ai-index-rail) - var(--xframe-ai-index-gap)));

    & > .xframe-frame-host {
      width: min(
        100%,
        var(--canvas-w),
        calc(100vw - 2 * {{pagePadding}} - var(--xframe-ai-index-rail) - var(--xframe-ai-index-gap)),
        calc(var(--xframe-frame-avail-h) * var(--canvas-w-num) / var(--canvas-h-num))
      );
    }
  }

  &[data-xframe-ai-index-collapsed] {
    margin-left: 0 !important;
    max-width: min(var(--canvas-w), calc(100vw - 2 * {{pagePadding}})) !important;

    & > .xframe-frame-host {
      width: min(
        100%,
        var(--canvas-w),
        calc(var(--xframe-frame-avail-h) * var(--canvas-w-num) / var(--canvas-h-num))
      ) !important;
    }
  }
}

/* frame-host — container-query context (experiment .frame-host) */
.xframe-frame-host {
  position: relative;
  width: min(
    100%,
    var(--canvas-w),
    calc(var(--xframe-frame-avail-h) * var(--canvas-w-num) / var(--canvas-h-num))
  );
  aspect-ratio: var(--canvas-w-num) / var(--canvas-h-num);
  container-type: inline-size;
  flex: 0 0 auto;
  overflow: hidden;
}

/* frame — logical canvas; slides live here (experiment #frame) */
#xframe-frame.xframe-frame {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--canvas-w);
  height: var(--canvas-h);
  transform-origin: top left;
  transform: scale(calc(100cqw / var(--canvas-w-num)));
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: var(--box-shadow, none);
  background: var(--surface-bg);
  overflow: hidden;

  & > .layout-segments {
    position: absolute;
    inset: 0;
    flex: none;
    min-height: 0;
    overflow: hidden;
  }
}

@media (max-width: 1100px) {
  #xframe[data-xframe-canvas]:has(.xframe-ai-index-control:not([hidden])) {
    margin-left: 0;
    max-width: min(var(--canvas-w), calc(100vw - 2 * {{pagePadding}}));

    & > .xframe-frame-host {
      width: min(
        100%,
        var(--canvas-w),
        calc(var(--xframe-frame-avail-h) * var(--canvas-w-num) / var(--canvas-h-num))
      );
    }
  }
}

/* Chrome — layout + frame alignment. Visual styling stays in hud.css.tmpl. */

#xframe-chrome {
  --xframe-chrome-pad-block: 0.75rem;
  --xframe-chrome-pad-inline: 0.75rem;
}

#xframe[data-xframe-canvas] > #xframe-chrome {
  position: relative;
  width: 100%;
  flex: 0 0 auto;
  box-sizing: border-box;
  min-height: calc(2.2rem + 2 * var(--xframe-chrome-pad-block));
  padding: var(--xframe-chrome-pad-block) var(--xframe-chrome-pad-inline);
}

#xframe-chrome .xframe-chrome-controls {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  column-gap: 1rem;
  width: 100%;
}

#xframe-chrome .hud {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  column-gap: 0.5rem;
  justify-self: center;
}

#xframe-chrome .hud-wing {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 5.5rem;
}

#xframe-chrome .hud-wing-left {
  justify-content: flex-end;
}

#xframe-chrome .hud-wing-right {
  justify-content: flex-start;
}

#xframe-chrome .xframe-audio-dock {
  display: flex;
  justify-content: center;
  align-items: center;
}

#xframe-chrome .xframe-chrome-wing-right {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Windowed — align chrome controls to the visible frame edges */
:root:not([data-xframe-fullscreen]) #xframe[data-xframe-canvas] > #xframe-chrome {
  & .xframe-chrome-controls {
    position: absolute;
    left: var(--frame-left, 0);
    width: var(--frame-width, 100%);
    top: 0;
    bottom: 0;
    z-index: 1;
  }
}

@media print {
  html, body {
    height: auto;
    overflow: visible;
  }

  #xframe[data-xframe-canvas] {
    max-width: none;
  }

  .xframe-frame-host {
    width: auto;
    height: auto;
    aspect-ratio: auto;
    container-type: normal;
    overflow: visible;
  }

  #xframe-frame.xframe-frame {
    position: relative;
    inset: auto;
    transform: none !important;
    border: 0;
    box-shadow: none;
  }
}

/* Fullscreen deck letterboxing + chrome overlay */

:root[data-xframe-fullscreen] {
  & html,
  & body {
    overflow: hidden;
    padding: 0;
  }
}

#xframe-deck {
  &:fullscreen,
  :root[data-xframe-fullscreen] & {
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    overflow: visible;
    justify-content: stretch;
    align-items: stretch;

    &:has(.xframe-ai-index-control:not([hidden])) {
      overflow: visible;
    }

    #xframe[data-xframe-canvas] {
      width: 100%;
      height: 100%;
      max-width: none;
      max-height: none;
      margin-left: 0;
      overflow: visible;

      &:has(.xframe-ai-index-control:not([hidden])) {
        margin-left: 0;
        max-width: none;
      }

      & > .xframe-frame-host {
        flex: 1 1 auto;
        width: 100%;
        height: 100%;
        min-height: 0;
        aspect-ratio: auto;
        container-type: normal;
        overflow: visible;
        background: transparent;
      }

      & > #xframe-chrome {
        position: absolute;
        inset: 0;
        z-index: 10;
        flex: none;
        width: auto;
        min-height: 0;
        padding: 0;
        pointer-events: none;
        background: transparent;
      }

      #xframe-chrome .xframe-chrome-controls {
        position: absolute;
        left: var(--frame-left, 0);
        width: var(--frame-width, 100%);
        top: calc(var(--frame-bottom, 100%) - 1rem);
        bottom: auto;
        transform: translateY(-100%);
        pointer-events: auto;
        column-gap: calc(1rem * var(--frame-scale, 1));
        z-index: 11;
      }

      #xframe-chrome .hud {
        font-size: calc(1rem * var(--frame-scale, 1));
        gap: calc(0.5rem * var(--frame-scale, 1));
        padding: calc(0.35rem * var(--frame-scale, 1)) calc(0.55rem * var(--frame-scale, 1));

        & .hud-wing {
          gap: calc(0.5rem * var(--frame-scale, 1));
          min-width: calc(5.5rem * var(--frame-scale, 1));
        }

        & button {
          padding: calc(0.35rem * var(--frame-scale, 1)) calc(0.65rem * var(--frame-scale, 1));
        }

        & [data-deck-counter] {
          min-width: calc(4.5rem * var(--frame-scale, 1));
          font-size: calc(0.9rem * var(--frame-scale, 1));
        }
      }

      #xframe-chrome .xframe-narrative audio {
        width: calc(15rem * var(--frame-scale, 1));
        height: calc(2.2rem * var(--frame-scale, 1));
      }

      /* Keep narration controls clear of the slide-number footer on the right. */
      #xframe-chrome .xframe-audio-dock {
        transform: translateX(calc(-3.25rem * var(--frame-scale, 1)));
      }

      #xframe-chrome .xframe-narrative-speak {
        min-width: calc(15rem * var(--frame-scale, 1));
        height: calc(2.2rem * var(--frame-scale, 1));
        font-size: calc(1rem * var(--frame-scale, 1));
      }
    }

    .xframe-ai-index-control {
      display: none !important;
    }

    #xframe-frame.xframe-frame {
      border: 0;
      border-radius: 0;
      box-shadow: none;
    }
  }
}

@media print {
.layout-container { display: block !important; height: auto !important; }
.layout-segments { overflow: visible !important; }
.layout-controls { display: none !important; }
#xframe-chrome { display: none !important; }
.segment {
  position: relative;
  display: block !important;
  page-break-after: always;
  min-height: 100vh;
}
}
